package com.campusfest.backend.competition;
import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/competitions") public class CompetitionController{private final CompetitionService service; public CompetitionController(CompetitionService s){service=s;} @GetMapping public List<CompetitionResponse> list(){return service.list();} @GetMapping("/{id}") public CompetitionResponse get(@PathVariable Long id){return CompetitionResponse.from(service.get(id));} @PostMapping @PreAuthorize("hasAnyRole('ORGANIZER','ADMIN')") public CompetitionResponse create(@Valid @RequestBody CompetitionRequest r,Authentication a){return service.create(r,a.getName());} @PutMapping("/{id}") @PreAuthorize("hasAnyRole('ORGANIZER','ADMIN')") public CompetitionResponse update(@PathVariable Long id,@Valid @RequestBody CompetitionRequest r,Authentication a){return service.update(id,r,a.getName());} @DeleteMapping("/{id}") @PreAuthorize("hasAnyRole('ORGANIZER','ADMIN')") public void delete(@PathVariable Long id,Authentication a){service.delete(id,a.getName());}}
